UPDATE kbd_entry SET category_id='虚拟机-016', ai_category_id='虚拟机-016', ai_category_conf=0.95, ai_category_reason='案例明确描述为''集群内虚拟机执行迁移时任务失败''，且故障原因为主机间SSH连接问题导致迁移中止。在HCI超融合架构中，集群内迁移通常涉及共享存储或本地存储的数据同步，属于典型的集群内热迁移场景。虽然未明确说明是否跨存储，但''集群内''是核心限定词，故优先匹配集群内热迁移分类。' WHERE id=276;
UPDATE kbd_entry SET category_id='虚拟机-017', ai_category_id='虚拟机-017', ai_category_conf=0.95, ai_category_reason='案例标题明确提到“跨集群迁移”，问题描述指出在迁移向导步骤中因目标集群SSH通信不兼容导致操作失败，属于典型的跨集群迁移功能异常。' WHERE id=285;
