UPDATE kbd_entry SET category_id='虚拟机-017', ai_category_id='虚拟机-017', ai_category_conf=0.95, ai_category_reason='标题明确提及“跨集群迁移”，描述中任务显示“失败”，尽管报错在兼容性处理阶段，但整体迁移任务状态为失败，最匹配跨集群迁移失败分类。' WHERE id=293;
UPDATE kbd_entry SET category_id='虚拟机-017', ai_category_id='虚拟机-017', ai_category_conf=0.95, ai_category_reason='标题明确提到“虚拟机跨集群迁移失败”，问题描述指出迁移任务显示失败且涉及兼容性处理，完全匹配该分类定义。' WHERE id=295;
UPDATE kbd_entry SET category_id='虚拟机-017', ai_category_id='虚拟机-017', ai_category_conf=0.98, ai_category_reason='标题明确提到“跨集群迁移”，问题描述中详细指出故障涉及“虚拟机跨集群热迁移功能”，且错误信息为“迁移失败”，完全匹配该分类定义。' WHERE id=317;
UPDATE kbd_entry SET category_id='虚拟机-015', ai_category_id='虚拟机-015', ai_category_conf=0.98, ai_category_reason='标题明确提及“跨存储迁移失败”，描述中确认为执行跨存储迁移任务时失败，完全匹配该分类定义。' WHERE id=318;
UPDATE kbd_entry SET category_id='虚拟机-017', ai_category_id='虚拟机-017', ai_category_conf=0.95, ai_category_reason='标题明确提及“跨集群迁移”，描述中涉及qemu进程加载，符合热迁移特征。' WHERE id=324;
UPDATE kbd_entry SET category_id='虚拟机-017', ai_category_id='虚拟机-017', ai_category_conf=0.95, ai_category_reason='标题明确提到“跨级群迁移”（即跨集群迁移），问题描述指出在迁移过程中因SSH鉴权失败导致迁移中断，完全匹配跨集群热迁移失败分类。' WHERE id=328;
UPDATE kbd_entry SET category_id='虚拟机-020', ai_category_id='虚拟机-020', ai_category_conf=0.98, ai_category_reason='标题核心关键词为“跨集群迁移失败”。问题描述明确指出操作场景为“执行虚机关机跨集群迁移”，即冷迁移（VM is powered off during migration）。故障现象为“同步虚拟磁盘数据失败”，这是冷迁移过程中典型的数据复制阶段错误。因此，该分类与案例完全匹配。' WHERE id=339;
UPDATE kbd_entry SET category_id='虚拟机-015', ai_category_id='虚拟机-015', ai_category_conf=0.95, ai_category_reason='案例描述明确提到“同集群跨主机热迁移”且进度卡在94%无法完成，属于典型的集群内热迁移失败场景。虽然HCI超融合通常共享存储，但分类列表中“虚拟机集群内热迁移失败（跨存储）”与“虚拟机集群内热迁移失败（同存储）”均涵盖集群内迁移，鉴于卡住现象常伴随数据同步或状态切换问题，此分类最为匹配。' WHERE id=343;
UPDATE kbd_entry SET category_id='虚拟机-017', ai_category_id='虚拟机-017', ai_category_conf=0.95, ai_category_reason='案例标题明确为“跨集群迁移报错”，问题描述中执行的是“迁移虚拟机到其他集群”操作，且在输入目的集群信息后报错，属于典型的跨集群迁移流程失败。' WHERE id=350;
UPDATE kbd_entry SET category_id='虚拟机-014', ai_category_id='虚拟机-014', ai_category_conf=0.95, ai_category_reason='案例核心问题是主机离线后尝试对GPU虚拟机进行迁移操作失败，提示不支持热迁移。这属于虚拟机迁移模块的功能限制或执行失败场景。虽然具体是热迁移还是冷迁移未完全明确，但归类于“虚拟机迁移”大类下的具体失败项最为准确。在提供的列表中，虚拟机-014至-020均涉及迁移失败，其中-014为通用SCMT迁移失败，常作为此类非特定存储/集群边界迁移问题的首选分类；若严格区分热/冷，可能对应-015/-016等，但鉴于GPU通常涉及特殊资源调度，且描述中强调“迁移该主机上的...”，-014或相关迁移子类最匹配。考虑到列表中存在更具体的跨存储/同存储热迁移，但GPU迁移失败往往被单独标记或归入通用迁移失败。此处选择虚拟机-014作为代表迁移功能异常的候选，或者更精确地看，如果系统将其视为一种特殊的迁移任务失败，它属于虚拟机迁移范畴。对比其他选项，无直接“GPU迁移失败”分类，故归入迁移类。' WHERE id=351;
UPDATE kbd_entry SET category_id='虚拟机-015', ai_category_id='虚拟机-015', ai_category_conf=0.95, ai_category_reason='标题明确为''虚拟机热迁移失败''，描述指出''集群内跨主机执行热迁移时失败''。虽然描述提到网络配置问题，但核心故障现象是热迁移失败。在HCI中，跨主机热迁移通常涉及共享存储或特定网络要求，若未明确提及同存储/跨存储，且存在网络干扰导致的中断，归类于热迁移失败最准确。考虑到描述中未明确区分是否跨存储，但''跨主机''隐含了可能的存储路径变化或网络依赖，虚拟机-015和016均为候选。通常''跨主机''若无特别说明''同存储''，往往默认检查存储兼容性或网络隔离性。然而，更精准的匹配应看是否有''同存储''字样。描述仅说''跨主机''。对比015(跨存储)和016(同存储)，由于HCI超融合架构下，跨主机热迁移通常是在同一虚拟存储池内进行（即逻辑上的同存储或分布式存储），因此''虚拟机集群内热迁移失败（同存储）''可能更符合常规HCI场景。但题目中未明确排除跨存储。让我们再看分类列表：虚拟机-015是跨存储，虚拟机-016是同存储。HCI平台通常使用分布式存储，虚拟机磁盘位于分布式存储上，跨主机迁移时数据不移动，属于''同存储''（指底层存储池一致）。因此虚拟机-016更贴切。但是，如果是因为网络问题导致迁移中断，根本原因是迁移功能失败。让我们重新审视：描述中提到“迁移网络被设置为存储口”，这暗示了网络配置错误导致的迁移失败。在HCI中，如果存储网络和迁移网络混用或配置不当，会导致迁移失败。无论底层存储如何，现象都是热迁移失败。在015和016之间，HCI的分布式存储特性使得跨主机迁移通常被视为“同存储”环境下的操作（因为数据在集群共享池中）。因此虚拟机-016比015更常见。但如果必须选一个最匹配的，且没有更多上下文，通常“热迁移失败”是一个大类。这里有两个细分。鉴于HCI的特性，跨主机迁移多为同存储（分布式块存储）。故首选016。等等，再仔细看描述：“强制切换场景下同样无法完成”。这确认了是热迁移。关于015 vs 016：如果用户使用的是外置存储（FC/ISCSI/NFS），则可能是跨存储或同存储。如果是内置虚拟存储，则是同存储。标题只写了【HCI】，通常指内置虚拟存储。因此**虚拟机-016: 虚拟机集群内热迁移失败（同存储）** 是最准确的。' WHERE id=359;
UPDATE kbd_entry SET category_id='虚拟机-017', ai_category_id='虚拟机-017', ai_category_conf=0.98, ai_category_reason='标题明确包含“跨集群迁移失败”，问题描述指出是在“开机状态下”执行“在线跨集群迁移”，这属于热迁移范畴。该分类精确匹配故障场景。' WHERE id=436;
UPDATE kbd_entry SET category_id='虚拟机-015', ai_category_id='虚拟机-015', ai_category_conf=0.85, ai_category_reason='案例核心涉及“虚拟机”、“跨存储迁移”及“开机时触发迁移”。虽然标题为修改速率，但问题本质是跨存储热迁移过程中的性能/配置限制。在现有分类中，这是最贴近“跨存储迁移”场景的分类。' WHERE id=456;
UPDATE kbd_entry SET category_id='虚拟机-049', ai_category_id='虚拟机-049', ai_category_conf=0.85, ai_category_reason='故障表现为Linux内部网络服务启动失败，导致网络不可用，属于虚拟机内部网络异常。' WHERE id=493;
UPDATE kbd_entry SET category_id='虚拟机-043', ai_category_id='虚拟机-043', ai_category_conf=0.85, ai_category_reason='案例描述为vGPU授权服务器部署后，网络连通性正常（ping通），但Web服务无法访问。这通常指向虚拟机操作系统内部的应用程序配置、防火墙策略或服务状态问题，属于虚拟机内部软件层面的故障，而非HCI平台底层组件或硬件故障。' WHERE id=531;
UPDATE kbd_entry SET category_id='虚拟机-017', ai_category_id='虚拟机-017', ai_category_conf=0.95, ai_category_reason='问题描述明确指出是在执行“跨集群迁移虚拟机”任务时出现异常，且任务无法结束/取消，属于迁移流程中的故障。虽然现象是卡住，但根本业务场景是跨集群迁移失败。' WHERE id=576;
UPDATE kbd_entry SET category_id='虚拟机-015', ai_category_id='虚拟机-015', ai_category_conf=0.85, ai_category_reason='问题描述明确指出故障发生在“虚拟机迁移过程中”，且导致“网络通信中断”。在HCI超融合架构中，虚拟机的在线迁移（热迁移）严重依赖Zookeeper进行状态同步和协调。Zookeeper重连异常通常会导致迁移任务卡住、失败或引发网络配置下发错误，进而造成虚拟机网络中断。虽然标题未直接写“迁移失败”，但现象是迁移过程中的副作用，归类于迁移相关故障最为准确。' WHERE id=608;
UPDATE kbd_entry SET category_id='虚拟机-016', ai_category_id='虚拟机-016', ai_category_conf=0.95, ai_category_reason='标题明确为“迁移...失败”，描述涉及在线迁移及网络异常，符合热迁移失败特征。' WHERE id=625;
UPDATE kbd_entry SET category_id='虚拟机-017', ai_category_id='虚拟机-017', ai_category_conf=0.98, ai_category_reason='标题明确为''跨集群热迁移失败''，问题描述涉及跨集群迁移任务在数据传输阶段失败，完全匹配该分类定义。' WHERE id=645;
UPDATE kbd_entry SET category_id='虚拟机-016', ai_category_id='虚拟机-016', ai_category_conf=0.95, ai_category_reason='案例核心故障为“主机进入单主机维护模式”时触发的“虚拟机迁移中断/失败”。在HCI超融合架构中，单主机维护通常涉及将虚拟机从该主机热迁移至集群内其他主机。由于是同一集群内的虚拟存储环境，且未提及跨存储或跨集群操作，故最匹配“虚拟机集群内热迁移失败（同存储）”。报错“获取镜像信息失败”是迁移过程中的具体错误原因，不影响对主故障现象（迁移失败）的分类。' WHERE id=646;
UPDATE kbd_entry SET category_id='虚拟机-015', ai_category_id='虚拟机-015', ai_category_conf=0.95, ai_category_reason='描述明确为迁移任务失败，错误涉及网口统计，通常发生在跨存储或复杂网络环境的迁移中。' WHERE id=648;
UPDATE kbd_entry SET category_id='虚拟机-017', ai_category_id='虚拟机-017', ai_category_conf=0.95, ai_category_reason='标题明确提及''跨集群迁移失败''，描述中涉及SSH端口状态获取失败导致迁移中断，完全匹配该分类。' WHERE id=654;
UPDATE kbd_entry SET category_id='虚拟机-016', ai_category_id='虚拟机-016', ai_category_conf=0.95, ai_category_reason='标题明确为''虚拟机热迁移失败''，且描述中涉及HCI超融合环境下的源/目标主机CPU兼容性检查失败，属于典型的集群内热迁移故障。' WHERE id=655;
UPDATE kbd_entry SET category_id='虚拟机-017', ai_category_id='虚拟机-017', ai_category_conf=0.95, ai_category_reason='标题明确为“跨集群迁移失败”，描述涉及同步虚拟磁盘数据阶段报错，符合跨集群热迁移场景。' WHERE id=665;
UPDATE kbd_entry SET category_id='虚拟机-016', ai_category_id='虚拟机-016', ai_category_conf=0.95, ai_category_reason='标题明确提及“迁移失败”，描述中确认为“虚拟机热迁移”且涉及“存储口”，符合HCI超融合架构下基于共享虚拟存储的热迁移场景。' WHERE id=670;
UPDATE kbd_entry SET category_id='虚拟机-017', ai_category_id='虚拟机-017', ai_category_conf=0.95, ai_category_reason='案例标题明确提到“纳管跨集群迁移虚拟机”，问题描述指出在SCP上执行该操作时源主机出现异常日志，核心故障场景为跨集群迁移过程中的逻辑错误（登录校验/网口速率获取），最匹配跨集群迁移失败的分类。' WHERE id=671;
UPDATE kbd_entry SET category_id='虚拟机-021', ai_category_id='虚拟机-021', ai_category_conf=0.85, ai_category_reason='标题核心为“迁移后”出现异常，属于虚拟机迁移场景。虽分类名含VMware，但作为迁移类故障最接近候选。' WHERE id=674;
UPDATE kbd_entry SET category_id='虚拟机-017', ai_category_id='虚拟机-017', ai_category_conf=0.95, ai_category_reason='案例标题明确为“跨集群迁移失败”，描述中提到“执行跨集群迁移虚拟机后...任务详情显示失败”。虽然未显式标注“热”迁移，但HCI中跨集群迁移通常默认为在线/热迁移场景，且故障发生在迁移流程的兼容性处理阶段，属于典型的跨集群迁移失败。' WHERE id=696;
UPDATE kbd_entry SET category_id='虚拟机-017', ai_category_id='虚拟机-017', ai_category_conf=0.95, ai_category_reason='标题明确为''虚拟机跨集群迁移失败''，描述中提及''目标集群创建网卡设备阶段失败''，属于跨集群迁移过程中的网络资源冲突导致迁移中止。' WHERE id=697;
UPDATE kbd_entry SET category_id='虚拟机-017', ai_category_id='虚拟机-017', ai_category_conf=0.95, ai_category_reason='案例明确描述为“跨集群迁移后”出现异常，属于跨集群迁移场景。虽然虚拟机已开机，但迁移后的网络配置未正确同步导致IP获取失败，归类于迁移相关故障最为准确。' WHERE id=722;
UPDATE kbd_entry SET category_id='虚拟机-017', ai_category_id='虚拟机-017', ai_category_conf=0.95, ai_category_reason='案例标题明确提到“跨集群迁移虚拟机失败”，问题描述中任务状态为“失败”且涉及“同步虚拟磁盘数据”，符合跨集群热迁移失败的典型特征。虽然标题提及密码特殊字符，但这通常是导致认证或通信失败进而引发迁移中断的原因，核心故障现象仍归类于迁移失败。' WHERE id=732;
UPDATE kbd_entry SET category_id='虚拟机-016', ai_category_id='虚拟机-016', ai_category_conf=0.95, ai_category_reason='案例标题和描述明确指出是''虚拟机迁移运行位置报错''、''迁移中止''，且发生在''HCI...ARM集群中执行虚拟机集群内或跨集群迁移时''。错误码0x010039DE通常关联于迁移过程中的命令执行失败。在HCI环境中，若无特殊说明跨存储，默认优先匹配同存储的热迁移失败场景，这是最常见的迁移故障类型。' WHERE id=735;
UPDATE kbd_entry SET category_id='虚拟机-017', ai_category_id='虚拟机-017', ai_category_conf=0.95, ai_category_reason='案例标题明确提到“同版本跨集群迁移”，问题描述指出在迁移向导中因获取远程主机IP掩码失败导致流程中断，属于典型的跨集群迁移失败场景。' WHERE id=751;
UPDATE kbd_entry SET category_id='虚拟机-017', ai_category_id='虚拟机-017', ai_category_conf=0.95, ai_category_reason='标题明确提到“虚拟机跨集群迁移...失败”，问题描述指出故障发生在“执行虚拟机跨集群迁移时，迁移任务中止”。虽然根本原因是存储满，但直接表现的故障现象是跨集群迁移操作失败，因此最匹配的分类是虚拟机跨集群热迁移失败。' WHERE id=755;
UPDATE kbd_entry SET category_id='虚拟机-017', ai_category_id='虚拟机-017', ai_category_conf=0.95, ai_category_reason='案例标题明确描述为“跨集群迁移虚拟机失败”，且问题发生在执行迁移任务的过程中。虽然未显式标注“热”迁移，但HCI中跨集群迁移通常默认为在线/热迁移场景，且错误涉及磁盘数据同步和SSH连接，符合跨集群迁移失败的典型特征。' WHERE id=762;
UPDATE kbd_entry SET category_id='虚拟机-015', ai_category_id='虚拟机-015', ai_category_conf=0.95, ai_category_reason='案例标题明确为“迁移虚拟机失败”，问题描述指出在“同步虚拟磁盘数据阶段中止”，且错误信息涉及“基镜像所有副本均不可用”。这通常发生在跨主机或跨存储的热迁移过程中，因为源端存储数据不可读导致无法同步。虽然未明确说是跨存储，但HCI中迁移失败常归类于此或同存储迁移。考虑到“同步虚拟磁盘数据”是迁移的核心步骤，且涉及底层存储副本状态，此分类最匹配业务场景。' WHERE id=778;
UPDATE kbd_entry SET category_id='虚拟机-043', ai_category_id='虚拟机-043', ai_category_conf=0.95, ai_category_reason='问题描述明确指出是在“英伟达授权服务器虚拟机内部”执行脚本配置IP时返回报错，属于虚拟机操作系统内部软件/工具运行异常，而非HCI平台层面的网络配置或硬件故障。' WHERE id=792;
UPDATE kbd_entry SET category_id='虚拟机-017', ai_category_id='虚拟机-017', ai_category_conf=0.95, ai_category_reason='问题描述明确指出在“SCP镜像分发”场景下，由模板派生的虚拟机执行“跨集群迁移”时报错。虽然报错内容是查询基镜像失败，但故障发生的直接操作是跨集群迁移，且该错误导致迁移流程中断，符合跨集群热迁移失败的分类定义。' WHERE id=793;
UPDATE kbd_entry SET category_id='虚拟机-018', ai_category_id='虚拟机-018', ai_category_conf=0.95, ai_category_reason='案例标题明确提到“批量跨存储冷迁移”，且问题描述为配置页面卡住导致迁移无法进行，属于典型的冷迁移失败场景。分类路径完全匹配：虚拟机 > 虚拟机迁移 > 虚拟机集群内或跨集群迁移失败 > 虚拟机集群内冷迁移失败（跨存储）。' WHERE id=800;
UPDATE kbd_entry SET category_id='虚拟机-016', ai_category_id='虚拟机-016', ai_category_conf=0.95, ai_category_reason='标题明确为“迁移虚拟机报错”，描述中提及migrate_config接口400错误，属于典型的虚拟机迁移失败场景。' WHERE id=814;
UPDATE kbd_entry SET category_id='虚拟机-017', ai_category_id='虚拟机-017', ai_category_conf=0.95, ai_category_reason='标题明确为“跨集群迁移失败”，描述中提及“执行虚拟机跨集群迁移时...校验阶段失败”，完全匹配该分类。' WHERE id=823;
UPDATE kbd_entry SET category_id='虚拟机-017', ai_category_id='虚拟机-017', ai_category_conf=0.95, ai_category_reason='标题明确提及''跨集群迁移虚拟机失败''，且描述中包含同步基镜像等典型热迁移步骤错误，完全匹配该分类。' WHERE id=827;
UPDATE kbd_entry SET category_id='虚拟机-017', ai_category_id='虚拟机-017', ai_category_conf=0.95, ai_category_reason='标题明确提到“批量跨集群迁移虚拟机”且报错导致迁移失败，完全匹配该分类定义。' WHERE id=847;
UPDATE kbd_entry SET category_id='虚拟机-017', ai_category_id='虚拟机-017', ai_category_conf=0.95, ai_category_reason='标题明确提及''跨集群迁移虚拟机''且报错，直接匹配跨集群迁移失败分类。' WHERE id=877;
UPDATE kbd_entry SET category_id='平台-002', ai_category_id='平台-002', ai_category_conf=0.85, ai_category_reason='案例标题明确指出''集群主机扩容了一台主机''，且后续问题表现为新主机在虚拟机迁移中不可选，这通常意味着主机扩容流程未完全成功或状态同步异常，导致资源池未能正确识别新节点。虽然操作看似完成，但功能缺失属于扩容相关的故障范畴。' WHERE id=912;
UPDATE kbd_entry SET category_id='虚拟机-016', ai_category_id='虚拟机-016', ai_category_conf=0.95, ai_category_reason='标题明确提及''热迁移''且为HCI平台常见场景，通常默认为同存储热迁移。' WHERE id=926;
UPDATE kbd_entry SET category_id='虚拟机-017', ai_category_id='虚拟机-017', ai_category_conf=0.95, ai_category_reason='案例标题明确提到“跨集群迁移”，且问题描述为任务一直显示排队中，属于迁移流程异常。在HCI场景中，跨集群迁移通常涉及存储和网络同步，若未特别说明关机，默认为热迁移场景。该分类最精准匹配“跨集群”和“迁移失败/卡住”的特征。' WHERE id=940;
UPDATE kbd_entry SET category_id='虚拟机-014', ai_category_id='虚拟机-014', ai_category_conf=0.95, ai_category_reason='案例标题明确提到“迁移虚拟机报错”，问题描述为“迁移虚拟机时报错查询基镜像信息失败”。在HCI超融合平台中，涉及跨集群或特定场景的虚拟机迁移通常归类于SCMT（Storage Cluster Migration Tool）或通用迁移故障。虽然分类列表中有多个迁移细分项（如热迁移、冷迁移），但“查询基镜像信息失败”通常发生在迁移前的元数据校验阶段，属于广义的迁移流程失败。在没有更具体的“跨集群”或“同存储”限定词时，SCMT迁移失败或通用的迁移失败是最贴切的匹配。若严格区分，虚拟机-017（跨集群热迁移）或虚拟机-020（跨集群冷迁移）也可能相关，但SCMT常作为底层迁移工具报错的直接对应分类。鉴于选项有限，虚拟机-014是涵盖此类迁移操作失败的最佳候选之一，或者如果系统默认将非特定类型的迁移错误归入SCMT或类似底层迁移机制。*修正思考*：重新审视分类列表，有 `虚拟机-014: 虚拟机scmt迁移失败`。SCMT通常指代一种特定的迁移方式或工具。如果报错是“查询基镜像信息失败”，这往往是迁移任务启动时的预检查错误。对比其他迁移选项：015/016是热迁移，018/019是冷迁移，017/020是跨集群。题目未说明是热还是冷，也未说明是否跨集群。但在很多HCI故障库中，非标准或底层迁移工具报错常被归类到SCMT或类似的迁移大类。然而，更常见的情况是，如果无法确定具体迁移类型，可能会选择最通用的迁移失败。这里没有“通用迁移失败”选项。考虑到“基镜像”概念常用于链接克隆或模板派生后的迁移，或者快照链处理，这与SCMT（可能涉及存储层迁移逻辑）高度相关。因此选014。' WHERE id=958;
UPDATE kbd_entry SET category_id='虚拟机-016', ai_category_id='虚拟机-016', ai_category_conf=0.95, ai_category_reason='案例标题和描述明确指出是“热升级之后”、“集群内跨主机迁移”失败，且报错为“操作已中断”，符合虚拟机在集群内进行热迁移失败的典型场景。由于是HCI超融合平台，通常默认使用共享虚拟存储，故归类为同存储热迁移失败最为匹配。' WHERE id=964;
UPDATE kbd_entry SET category_id='虚拟机-015', ai_category_id='虚拟机-015', ai_category_conf=0.95, ai_category_reason='标题明确提及“迁移失败”，描述涉及基镜像异常导致的迁移报错，属于典型的虚拟机迁移故障。' WHERE id=1034;
UPDATE kbd_entry SET category_id='虚拟机-016', ai_category_id='虚拟机-016', ai_category_conf=0.95, ai_category_reason='案例描述中明确提到在''vs存储上执行迁移运行位置操作''，且故障表现为KVM进程core dump导致迁移中断。由于是在同一虚拟存储（VS）内部进行的迁移操作，符合''集群内热迁移失败（同存储）''的定义。' WHERE id=1040;
UPDATE kbd_entry SET category_id='虚拟机-018', ai_category_id='虚拟机-018', ai_category_conf=0.95, ai_category_reason='案例标题明确描述为“本地存储冷迁移虚拟机到虚拟失败”，即从本地存储迁移至虚拟存储，属于跨存储的冷迁移操作。问题现象中的报错“同步虚拟磁盘数据失败”直接对应迁移过程中的数据同步环节，完全符合该分类定义。' WHERE id=1054;
UPDATE kbd_entry SET category_id='虚拟机-018', ai_category_id='虚拟机-018', ai_category_conf=0.95, ai_category_reason='标题明确提及“冷迁移”，且描述中“卡在9%”表明迁移过程异常或停滞，符合冷迁移失败的特征。' WHERE id=1059;
UPDATE kbd_entry SET category_id='虚拟机-016', ai_category_id='虚拟机-016', ai_category_conf=0.95, ai_category_reason='案例标题和描述明确指出故障现象为“虚拟机热迁移报错”、“热迁移时失败”。在HCI超融合架构中，原地热升级通常发生在同一集群内的主机上，且未提及跨存储操作，因此最匹配的分类是“虚拟机集群内热迁移失败（同存储）”。' WHERE id=1062;
UPDATE kbd_entry SET category_id='虚拟机-014', ai_category_id='虚拟机-014', ai_category_conf=0.95, ai_category_reason='案例标题明确描述为“虚拟机迁移失败”，且问题核心在于带有虚拟共享盘或物理盘的虚拟机在迁移过程中因磁盘配置缺失导致同步数据失败。虽然未显式提及SCMT，但在HCI超融合语境下，涉及存储类型转换或特定磁盘配置的迁移故障常归类于此类高级迁移场景，或者作为最接近的“迁移失败”具体子类。' WHERE id=1072;
