UPDATE kbd_entry SET category_id='虚拟机-041', ai_category_id='虚拟机-041', ai_category_conf=0.85, ai_category_reason='案例描述为虚拟机控制台显示中文乱码（方块），属于虚拟机图形化界面/桌面显示异常。在提供的分类列表中，''虚拟机内部黑屏''是''进不去系统OS或桌面''下的最接近的显示类故障分类，通常涵盖控制台画面渲染、字体缺失导致的显示错误等问题。' WHERE id=1223;
UPDATE kbd_entry SET category_id='硬件-012', ai_category_id='硬件-012', ai_category_conf=0.85, ai_category_reason='案例核心现象为断电重启后CPU和内存识别数量减半，这通常由物理硬件损坏或接触不良导致。虽然标题明确提到''CPU物理损坏''，但分类列表中无直接的''CPU物理损坏''项，而''内存ECC故障''是硬件层面对内存容量/状态异常的最接近匹配（常伴随CPU通道故障导致内存不可用）。此外，存储网口灰色属于网卡问题，但主因是CPU/内存识别异常，故优先归类于硬件资源识别故障。' WHERE id=1357;
UPDATE kbd_entry SET category_id='虚拟机-043', ai_category_id='虚拟机-043', ai_category_conf=0.95, ai_category_reason='案例核心故障是第三方杀毒软件（卡巴斯基）的防火墙策略导致域共享功能不可用，属于虚拟机操作系统内部软件配置或行为导致的业务异常。' WHERE id=1488;
