UPDATE kbd_entry SET category_id='虚拟机-043', ai_category_id='虚拟机-043', ai_category_conf=0.95, ai_category_reason='故障核心是Windows操作系统内部的组策略配置限制了RDP连接数，属于虚拟机内部系统组件/软件配置导致的功能异常。虽然标题提到“开机后”，但并非“开机失败”（VM已正常启动），而是启动后的远程访问功能受限，符合内部软件使用异常的定义。' WHERE id=1611;
