UPDATE kbd_entry SET category_id='虚拟机-017', ai_category_id='虚拟机-017', ai_category_conf=0.95, ai_category_reason='案例标题明确指出故障场景为“跨集群热迁移”，问题描述中详细说明了在跨集群热迁移过程中任务失败。虽然报错信息包含“启动失败”，但这是迁移过程中的子步骤错误，根本故障现象是迁移操作本身失败，因此最匹配的分类是跨集群热迁移失败。' WHERE id=2280;
UPDATE kbd_entry SET category_id='虚拟机-017', ai_category_id='虚拟机-017', ai_category_conf=0.95, ai_category_reason='案例标题明确描述为“跨集群热迁移”，且问题表现为迁移进度卡在88%无法完成，属于典型的跨集群热迁移失败场景。虽然根本原因是LVM不支持优化拷贝导致数据量过大，但故障现象归类于迁移操作失败。' WHERE id=2291;
