UPDATE kbd_entry SET category_id='虚拟机-021', ai_category_id='虚拟机-021', ai_category_conf=0.85, ai_category_reason='案例核心为“虚拟机迁移”后出现配置问题导致业务不可用。虽然标题未直接说“迁移失败”，但迁移后的状态异常（通信口未配、VDC地址错）属于迁移流程或迁移后验证的范畴，且分类列表中无专门的“迁移后配置错误”项，故归入最相关的迁移类故障。' WHERE id=2426;
