UPDATE kbd_entry SET category_id='虚拟机-017', ai_category_id='虚拟机-017', ai_category_conf=0.95, ai_category_reason='案例标题明确提到“跨集群迁移失败”，问题描述指出是“单台虚拟机跨集群迁移”过程中失败，且涉及网络中断导致的读写错误，符合跨集群热迁移失败的典型特征。' WHERE id=2445;
UPDATE kbd_entry SET category_id='虚拟机-017', ai_category_id='虚拟机-017', ai_category_conf=0.95, ai_category_reason='标题明确提及''SCP跨集群迁移''，描述中执行的是''跨集群迁移''操作且失败。虽然描述提到''已关机''，但SCP通常指在线/近在线迁移场景，且分类列表中无专门的''跨集群冷迁移''细分项（仅有同存储/跨存储的集群内冷迁移），故最匹配跨集群迁移失败大类。' WHERE id=2454;
