UPDATE kbd_entry SET category_id='平台-006', ai_category_id='平台-006', ai_category_conf=0.95, ai_category_reason='问题描述明确指出根本原因是“版本缺陷导致系统分区写满”，进而影响SSH密码验证文件读取。虽然表象是迁移失败，但核心故障点是主机系统盘/分区空间耗尽，符合该分类定义。' WHERE id=2468;
UPDATE kbd_entry SET category_id='硬件-020', ai_category_id='硬件-020', ai_category_conf=0.95, ai_category_reason='标题明确提到''磁盘硬件故障''、''RAID卡无法识别0号盘''及''磁盘离线告警''，完全匹配单盘离线/不识别的硬件故障分类。' WHERE id=2488;
UPDATE kbd_entry SET category_id='虚拟机-043', ai_category_id='虚拟机-043', ai_category_conf=0.95, ai_category_reason='案例描述为VDI虚拟机重启后，网卡驱动正常且网络连通性正常，但Windows系统自带的“网络管理”界面图标显示空白。这属于操作系统内部组件或UI渲染逻辑异常，而非底层虚拟化硬件故障或网络连接故障。虽然标题包含“启动异常”，但指的是“系统服务启动异常”导致的UI显示问题，并非虚拟机开机失败（虚拟机-003），因此归类为内部软件/OS组件使用异常最为准确。' WHERE id=2516;
UPDATE kbd_entry SET category_id='硬件-020', ai_category_id='硬件-020', ai_category_conf=0.95, ai_category_reason='案例核心问题是加装NVMe硬盘后系统无法识别，且明确指出原因是缺少U.2套件导致物理连接失败。这属于典型的硬件层面硬盘不识别故障。虽然涉及两块盘，但通常此类分类涵盖单盘或多盘的不识别场景，若有多盘专用分类可考虑，但此处''硬盘离线或不识别''是最直接的匹配。' WHERE id=2518;
UPDATE kbd_entry SET category_id='硬件-020', ai_category_id='硬件-020', ai_category_conf=0.95, ai_category_reason='案例明确描述为“一块SSD磁盘运行中离线”，且通过物理重新插拔解决，属于典型的单块物理硬盘因接触不良导致的离线故障。' WHERE id=2529;
UPDATE kbd_entry SET category_id='硬件-020', ai_category_id='硬件-020', ai_category_conf=0.85, ai_category_reason='案例核心现象为“磁盘离线虚假告警”，虽然根因是时间修改导致的缓存误判，但在故障分类体系中，直接表现为磁盘状态异常（离线）的问题通常归类于硬件层的磁盘离线类别。' WHERE id=2620;
UPDATE kbd_entry SET category_id='硬件-020', ai_category_id='硬件-020', ai_category_conf=0.95, ai_category_reason='案例核心问题是替换磁盘后平台无法识别，且确认为原槽位硬件故障导致连接异常。这属于物理层面的硬盘不识别问题，符合''硬件 > 硬盘 > 硬盘离线或不识别''分类。' WHERE id=2652;
UPDATE kbd_entry SET category_id='硬件-020', ai_category_id='硬件-020', ai_category_conf=0.95, ai_category_reason='案例核心为NVMe缓存盘因槽位硬件异常导致离线，更换后恢复，符合单盘离线特征。' WHERE id=2667;
UPDATE kbd_entry SET category_id='硬件-020', ai_category_id='硬件-020', ai_category_conf=0.95, ai_category_reason='案例核心问题是磁盘在物理移动后，操作系统层面（lsblk）无法识别该磁盘，尽管RAID卡已识别。这属于典型的硬盘不识别故障。由于是单块磁盘的问题，匹配''硬盘离线或不识别（单盘）''最为准确。' WHERE id=2678;
UPDATE kbd_entry SET category_id='硬件-020', ai_category_id='硬件-020', ai_category_conf=0.95, ai_category_reason='案例核心故障现象为''slot4槽位磁盘无法识别''，且确认为背板线缆损坏导致的物理层问题。分类列表中''硬件 > 硬盘 > 硬盘离线或不识别''最匹配此场景。由于仅涉及单个槽位/单块盘的识别问题，故选择''单盘''子类。' WHERE id=2696;
UPDATE kbd_entry SET category_id='虚拟机-016', ai_category_id='虚拟机-016', ai_category_conf=0.95, ai_category_reason='案例标题和描述明确指出是''HCI集群内''的''虚拟机热迁移任务失败''。在超融合架构中，默认的热迁移通常发生在同一虚拟存储池内（同存储），且故障原因涉及VN服务同步导致vslink状态获取失败，属于典型的集群内热迁移流程中断。' WHERE id=2767;
UPDATE kbd_entry SET category_id='虚拟机-017', ai_category_id='虚拟机-017', ai_category_conf=0.85, ai_category_reason='案例核心为跨集群迁移场景，虽表现为速率慢而非彻底失败，但在现有分类体系中，跨集群迁移性能/效率问题通常归类于迁移相关故障。' WHERE id=2772;

